const ownerIdPattern = /^[A-Za-z0-9_-]{1,128}$/;
const fileNamePattern =
    /^[a-f0-9]{8}-(?:[a-f0-9]{4}-){3}[a-f0-9]{12}\.(?:jpg|png|webp)$/i;

// Allow only listing-photo paths generated by our backend.
export function isListingPhotoPath(ownerId, fileName) {
    return (
        ownerIdPattern.test(ownerId) &&
        fileNamePattern.test(fileName)
    );
}

// Keep listing photos separate from existing profile pictures.
export function listingPhotoKey(ownerId, fileName) {
    if (!isListingPhotoPath(ownerId, fileName)) {
        throw new Error("Invalid listing photo path");
    }

    return `listing-photos/${ownerId}/${fileName}`;
}

// Serve listing photos through our backend, not a public R2 bucket.
export function listingPhotoUrl(baseUrl, ownerId, fileName) {
    listingPhotoKey(ownerId, fileName);

    const origin = new URL(baseUrl).origin;

    return `${origin}/api/uploads/listing-photos/${ownerId}/${fileName}`;
}
